/* HashiBot V2 Step 16 — Telegram Platform. Event-driven communications only; no trading control. */
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE public.telegram_channel_category AS ENUM ('FREE','VIP','ADMIN_OPS'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.telegram_delivery_status AS ENUM ('queued','sending','delivered','failed','dead_letter','skipped'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.telegram_bots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bot_key text NOT NULL UNIQUE, name text NOT NULL, token_secret_ref text NOT NULL, is_default boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.telegram_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bot_id uuid REFERENCES public.telegram_bots(id) ON DELETE SET NULL, channel_key text NOT NULL UNIQUE, category public.telegram_channel_category NOT NULL, display_name text NOT NULL, chat_id_secret_ref text NOT NULL, enabled boolean NOT NULL DEFAULT true, admin_only boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.telegram_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_key text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', body text NOT NULL, parse_mode text NOT NULL DEFAULT 'Markdown', enabled boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.telegram_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_key text NOT NULL UNIQUE, event_type text NOT NULL, source text NOT NULL DEFAULT '*', channel_category public.telegram_channel_category NOT NULL, template_key text NOT NULL REFERENCES public.telegram_templates(template_key), min_severity text NOT NULL DEFAULT 'debug', admin_only boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true, priority integer NOT NULL DEFAULT 100, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.customer_telegram_preferences (customer_id uuid PRIMARY KEY REFERENCES public.customers(id) ON DELETE CASCADE, telegram_enabled boolean NOT NULL DEFAULT false, telegram_chat_id text NOT NULL DEFAULT '', muted_categories public.telegram_channel_category[] NOT NULL DEFAULT '{}', muted_event_types text[] NOT NULL DEFAULT '{}', quiet_hours jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.telegram_delivery_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid REFERENCES public.engine_events(id) ON DELETE SET NULL, customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL, route_id uuid REFERENCES public.telegram_routes(id) ON DELETE SET NULL, channel_id uuid REFERENCES public.telegram_channels(id) ON DELETE SET NULL, template_key text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', rendered_message text NOT NULL DEFAULT '', status public.telegram_delivery_status NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.telegram_delivery_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), queue_id uuid REFERENCES public.telegram_delivery_queue(id) ON DELETE SET NULL, event_id uuid REFERENCES public.engine_events(id) ON DELETE SET NULL, channel_id uuid REFERENCES public.telegram_channels(id) ON DELETE SET NULL, status public.telegram_delivery_status NOT NULL, provider_message_id text NOT NULL DEFAULT '', error text NOT NULL DEFAULT '', request_snapshot jsonb NOT NULL DEFAULT '{}', response_snapshot jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_telegram_routes_event ON public.telegram_routes(event_type, enabled, priority);
CREATE INDEX IF NOT EXISTS idx_telegram_queue_status_next ON public.telegram_delivery_queue(status, next_attempt_at);
CREATE INDEX IF NOT EXISTS idx_telegram_logs_queue ON public.telegram_delivery_logs(queue_id, created_at DESC);
INSERT INTO public.telegram_bots (bot_key, name, token_secret_ref, is_default) VALUES ('default','HashiBot Telegram Bot','TELEGRAM_BOT_TOKEN',true) ON CONFLICT (bot_key) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.telegram_channels (bot_id, channel_key, category, display_name, chat_id_secret_ref, admin_only) SELECT b.id, v.channel_key, v.category::public.telegram_channel_category, v.display_name, v.chat_id_secret_ref, v.admin_only FROM public.telegram_bots b CROSS JOIN (VALUES ('free','FREE','Free Telegram Channel','TELEGRAM_FREE_CHAT_ID',false),('vip','VIP','VIP Telegram Channel','TELEGRAM_VIP_CHAT_ID',false),('admin_ops','ADMIN_OPS','Admin Ops Telegram Channel','TELEGRAM_ADMIN_OPS_CHAT_ID',true)) AS v(channel_key,category,display_name,chat_id_secret_ref,admin_only) WHERE b.bot_key='default' ON CONFLICT (channel_key) DO UPDATE SET display_name=EXCLUDED.display_name;
INSERT INTO public.telegram_templates (template_key, description, body) VALUES
('free_sample_signal','Free sample signal','📊 Sample setup: {{symbol}} {{side}} near {{entry}}. Upgrade for full risk plan and management.'),('vip_full_signal','VIP full signal','🚀 VIP Signal {{symbol}} {{side}}\nEntry: {{entry}}\nSL: {{sl}}\nTP: {{tp}}\nRisk: {{risk}}'),('signal_update','Signal update','🔄 Signal update for {{symbol}}: {{update}}'),('trade_opened','Trade opened','✅ Trade opened: {{symbol}} {{side}} at {{price}}'),('tp_hit','TP hit','🎯 TP hit on {{symbol}} at {{price}}'),('sl_hit','SL hit','🛑 SL hit on {{symbol}} at {{price}}'),('be_moved','BE moved','🟰 Break-even moved for {{symbol}} to {{price}}'),('protection_repaired','Protection repaired','🛡️ Protection repaired for {{symbol}}: {{detail}}'),('trade_closed','Trade closed','🏁 Trade closed: {{symbol}} result {{result}}'),('admin_error','Admin error','🚨 Admin error from {{source}}: {{message}}'),('provider_health_alert','Provider health alert','⚕️ Provider health alert {{provider}}: {{status}}'),('queue_backlog_alert','Queue backlog alert','📦 Queue backlog alert: {{queue}} has {{count}} pending'),('payment_approval','Payment approval','✅ Payment approved for {{customer}}. Subscription: {{package}}'),('subscription_expiry','Subscription expiry','⏳ Subscription expiring {{expires_at}}. Renew to keep VIP access.'),('daily_market_summary','Daily market summary','🌅 Daily market summary: {{summary}}'),('weekly_performance_summary','Weekly performance summary','📈 Weekly performance: {{summary}}') ON CONFLICT (template_key) DO UPDATE SET body=EXCLUDED.body;
INSERT INTO public.telegram_routes (route_key,event_type,channel_category,template_key,min_severity,admin_only,priority) VALUES
('signal_sample_free','signal.sample','FREE','free_sample_signal','debug',false,10),('signal_created_vip','signal.created','VIP','vip_full_signal','debug',false,10),('signal_updated_vip','signal.updated','VIP','signal_update','debug',false,10),('trade_opened_vip','trade.opened','VIP','trade_opened','debug',false,10),('tp_hit_vip','trade.tp_hit','VIP','tp_hit','debug',false,10),('sl_hit_vip','trade.sl_hit','VIP','sl_hit','debug',false,10),('be_moved_vip','trade.be_moved','VIP','be_moved','debug',false,10),('trade_closed_vip','trade.closed','VIP','trade_closed','debug',false,10),('protection_repaired_admin','protection.repaired','ADMIN_OPS','protection_repaired','warning',true,10),('admin_error_admin','admin.error','ADMIN_OPS','admin_error','error',true,10),('provider_health_admin','provider.health_alert','ADMIN_OPS','provider_health_alert','warning',true,10),('queue_backlog_admin','queue.backlog','ADMIN_OPS','queue_backlog_alert','warning',true,10),('payment_approval_admin','payment.approved','ADMIN_OPS','payment_approval','debug',true,10),('subscription_expiry_vip','subscription.expiry','VIP','subscription_expiry','debug',false,10),('daily_summary_free','market.daily_summary','FREE','daily_market_summary','debug',false,10),('weekly_performance_free','performance.weekly_summary','FREE','weekly_performance_summary','debug',false,10) ON CONFLICT (route_key) DO UPDATE SET template_key=EXCLUDED.template_key;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['telegram_bots','telegram_channels','telegram_templates','telegram_routes','telegram_delivery_queue','telegram_delivery_logs','customer_telegram_preferences'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.log_telegram_delivery(p_queue_id uuid, p_status public.telegram_delivery_status, p_provider_message_id text DEFAULT '', p_error text DEFAULT '', p_response jsonb DEFAULT '{}'::jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN INSERT INTO public.telegram_delivery_logs(queue_id,status,provider_message_id,error,response_snapshot) VALUES (p_queue_id,p_status,p_provider_message_id,p_error,p_response) RETURNING id INTO v_id; PERFORM public.platform_audit('telegram.delivery_logged','telegram_delivery_queue',p_queue_id,NULL,jsonb_build_object('status',p_status,'error',p_error)); RETURN v_id; END; $$;
